            )

            println("Real-time ${change.type} for pasture '${remotePasture.name}' (FS ID: $firestoreId), updatedBy: ${remotePasture.updatedBy}, remoteUpdatedAt: ${remotePasture.lastSyncAt}")

            when (change.type) {
                DocumentChange.Type.ADDED -> {
